import { createSdkMcpServer, query, tool } from "@anthropic-ai/claude-agent-sdk";
import { z } from "zod";

const kbSearch = tool(
  "kb_search", // the model sees this name as mcp__nova__kb_search
  "Search the R&D knowledge base. Returns the best page and one key fact.", // the model reads this to decide when to call
  { question: z.string().describe("what you want to know") }, // zod shape: the SDK checks the input for you
  async ({ question }) => {
    console.log("tool called with:", question);
    return { content: [{ type: "text", text: "brain/sandbox-sizes.md@a1b2c3: lite VMs have 4 vCPU" }] };
  },
);

const nova = createSdkMcpServer({ name: "nova", tools: [kbSearch] }); // runs inside this process

for await (const msg of query({
  prompt: "Use kb_search to find how many vCPUs a lite VM has. Answer in one line.",
  options: {
    model: "claude-haiku-5-5",
    effort: "low",
    settingSources: [],
    mcpServers: { nova }, // the key is the server name
    allowedTools: ["mcp__nova__kb_search"], // mcp__<server>__<tool>
    permissionMode: "dontAsk",
  },
})) {
  if (msg.type === "result" && msg.subtype === "success") console.log("answer:", msg.result);
}

import { createSdkMcpServer, tool } from "@anthropic-ai/claude-agent-sdk/core";
import { z } from "zod";

export const askHuman = tool("ask_human", "Ask the requester one question in the ticket's thread.",
  { question: z.string() },
  async ({ question }) => ({ content: [{ type: "text", text: await broker.ask(question) }] }));

export const postProgress = tool("post_progress", "Post a short progress update to the ticket's thread.",
  { text: z.string().max(400) },
  async ({ text }) => { await broker.post(text); return { content: [{ type: "text", text: "posted" }] }; });

export const kbSearch = tool("kb_search", "Search the R&D brain. Returns path@sha and the key fact per page.",
  { query: z.string() },
  async ({ query }) => ({ content: [{ type: "text", text: await runKbCli(query) }] })); // `kb search` over $KB_DIR

export const nova = createSdkMcpServer({ name: "nova", tools: [askHuman, postProgress, kbSearch] });
